import { canonicalHost } from "./credentials-BTv2IfUZ.js";
import "./nexus-root-BlPwOusj.js";
import { cutWorkingDraft } from "./apps-DlVsVHQ5.js";
import { CliError } from "./client-sMzq2PWG.js";
import { resolveClient, withErrorHandling } from "./_lifecycle-shared-_9BzQ9Y2.js";
import { readExecutaIdentity } from "./executa-cache-BFoUtb4J.js";
import { readExecutasLock, writeExecutasLock } from "./bundled-executas-BRyQkI9u.js";
import { loadAppManifest, loadExecutaManifest } from "./manifest-B_DjigtQ.js";
import "./executas-CvQY_w2U.js";
import "./executa-publish-BKnsUoZq.js";
import "./binary-upload-DVhQ0uY0.js";
import { uploadExecutaBinaries } from "./executa-upload-binaries-DwWQ18Dq.js";
import "./dev-ClCDRplP.js";
import "./executa-install-CM4x4doq.js";
import "./app-cache-Cr3tKbux.js";
import { resolveAppBySlugOrCache } from "./working-orchestration-CKXkvXVC.js";
import { resolve } from "node:path";
import { existsSync } from "node:fs";
import { bold, cyan, dim, green, yellow } from "kleur/colors";

//#region src/commands/apps-cut.ts
/**
* Pre-cut step (design executa-binary-direct-upload.md §7.3): every bundled
* executa that declares `distribution.binary_artifacts` gets its bytes
* pushed to the platform BEFORE the freeze, so the server-side executa
* version snapshot pins CDN URLs + sha256 (and `ensure_binaries_ready`
* passes without any pull-mirror fetch). Content-addressed idempotency
* makes re-cuts free: an already-published artifact set is all-`exists`.
*
* Executas using `binary_urls` (pull-mirror track) or no distribution are
* untouched. Missing tool_id (never pushed) is a hard error — the freeze
* would fail anyway, so surface the actionable message here.
*/
async function preUploadBundledBinaries(params) {
	const { client, host, cwd, dryRun, json } = params;
	const log = (msg) => {
		if (!json) console.log(msg);
	};
	if (!existsSync(resolve(cwd, "manifest.json"))) return;
	let appManifest;
	try {
		appManifest = loadAppManifest(cwd);
	} catch {
		return;
	}
	if (appManifest.bundledExecutas.length === 0) return;
	const lock = readExecutasLock(cwd, host);
	for (const decl of appManifest.bundledExecutas) {
		const dir = resolve(cwd, decl.path);
		let exManifest;
		try {
			exManifest = loadExecutaManifest(dir);
		} catch {
			continue;
		}
		const artifacts = exManifest.distribution?.binaryArtifacts;
		if (!artifacts || Object.keys(artifacts).length === 0) {
			if (exManifest.distribution?.type === "binary" && exManifest.distribution?.binaryUrls) log(yellow(`! "${decl.handle}" uses binary_urls (pull-mirror): the platform must be able to GET these URLs anonymously at cut/release. Private source URLs are deprecated — switch to binary_artifacts (direct upload) if the source is private.`));
			continue;
		}
		const identity = readExecutaIdentity(dir);
		const toolId = (identity && identity.host === canonicalHost(host) ? identity.tool_id : void 0) ?? lock?.executas[decl.handle]?.tool_id;
		if (!toolId) throw new CliError(`bundled executa "${decl.handle}" declares binary_artifacts but has no minted tool_id — run \`anna-app apps push\` once to register it, then re-run cut`, 4);
		if (dryRun) {
			log(yellow(`[dry-run] would upload binary_artifacts for "${decl.handle}" (${toolId})`));
			continue;
		}
		log(dim(`↑ uploading binary artifacts for "${decl.handle}" (${toolId})…`));
		const up = await uploadExecutaBinaries({
			client,
			host,
			dir,
			manifest: exManifest,
			toolId,
			fetchImpl: params.fetchImpl,
			log
		});
		log(green(`✓ "${decl.handle}": binaries ready `) + dim(`(${up.uploaded.length} uploaded, ${up.skipped.length} cached)`));
	}
}
async function runAppsCut(opts) {
	return withErrorHandling(async () => {
		const { client, host } = resolveClient({
			account: opts.account,
			fetchImpl: opts.fetchImpl
		});
		const app = await resolveAppBySlugOrCache(client, host, {
			slug: opts.slug,
			cwd: opts.cwd
		});
		await preUploadBundledBinaries({
			client,
			host,
			cwd: resolve(opts.cwd ?? process.cwd()),
			dryRun: opts.dryRun === true,
			json: opts.json === true,
			fetchImpl: opts.fetchImpl
		});
		if (opts.dryRun) {
			if (!opts.json) console.log(yellow(`[dry-run] would cut version ${opts.version} for apps/${app.slug} (app_id=${app.id})`));
			return 0;
		}
		let result;
		try {
			result = await cutWorkingDraft(client, app.id, {
				version: opts.version,
				changelog: opts.changelog
			});
		} catch (e) {
			if (e instanceof CliError && e.status === 409) throw new CliError(`version ${opts.version} already cut for apps/${app.slug}; choose a higher SemVer (e.g. bump patch/minor) and retry`, 9);
			if (e instanceof CliError && (e.status === 400 || e.status === 422)) throw new CliError(`cannot cut: ${e.message} — fix the working draft and \`apps push\` again`, 4);
			throw e;
		}
		if (result.frozen_executas.length > 0) {
			const cwd = resolve(opts.cwd ?? process.cwd());
			const lock = readExecutasLock(cwd, host);
			if (lock) {
				const byToolId = new Map(Object.entries(lock.executas).map(([h, e]) => [e.tool_id, h]));
				for (const fr of result.frozen_executas) {
					const handle = byToolId.get(fr.tool_id);
					if (handle && lock.executas[handle]) lock.executas[handle] = {
						...lock.executas[handle],
						tool_id: fr.tool_id,
						source: "cut"
					};
				}
				writeExecutasLock(cwd, {
					$schema: "anna-executas-lock/v1",
					host: canonicalHost(host),
					executas: lock.executas
				});
			}
		}
		if (opts.json) {
			console.log(JSON.stringify({
				app_id: app.id,
				slug: app.slug,
				host,
				version_id: result.version_id,
				version: result.version,
				frozen_executas: result.frozen_executas,
				bundle: result.bundle
			}, null, 2));
			return 0;
		}
		console.log(green(`✓ apps/${app.slug}: cut immutable version ${result.version} `) + dim(`(version_id=${result.version_id})`));
		for (const fr of result.frozen_executas) console.log(dim(`  froze ${fr.tool_id} → executa_version=${fr.executa_version_id}`) + (fr.version ? dim(` (v${fr.version})`) : ""));
		if (result.bundle && typeof result.bundle === "object") {
			const prefix = result.bundle.object_prefix;
			if (prefix) console.log(dim(`  bundle frozen at ${prefix}`));
		}
		console.log(dim(`→ run `) + cyan(`anna-app apps release ${result.version}`) + dim(` to go live`));
		console.log(bold(cyan(`status: ${app.status}`)));
		return 0;
	});
}

//#endregion
export { runAppsCut };